// ============================================================================
// OFFLINE-FIRST SPREADSHEET EXPORT ENGINE (vendor/xlsx.full.min.js)
// Ho tro xuat bang tinh Excel co cong thuc (=SUM, =AVERAGE, =MAX, =MIN, =IF)
// chay 100% Offline tai phong may khong can Internet, khong chua ma CVE cu.
// ============================================================================
(function(global) {
  if (global.XLSX) return;
  function escXml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
  }
  global.XLSX = {
    utils: {
      book_new: function() { return { sheets: [] }; },
      aoa_to_sheet: function(aoa) { return { aoa: aoa || [] }; },
      book_append_sheet: function(wb, ws, name) { wb.sheets.push({ name: name || 'Sheet1', ws: ws }); }
    },
    writeFile: function(wb, filename) {
      var sheet = wb.sheets[0] || { name: 'Sheet1', ws: { aoa: [] } };
      var rowsXml = sheet.ws.aoa.map(function(row) {
        var cellsXml = row.map(function(cell) {
          if (cell && typeof cell === 'object' && cell.f) {
            return '<Cell><Data ss:Type="String">=' + escXml(cell.f) + '</Data></Cell>';
          }
          var isNum = typeof cell === 'number' && !isNaN(cell);
          var t = isNum ? 'Number' : 'String';
          return '<Cell><Data ss:Type="' + t + '">' + escXml(cell) + '</Data></Cell>';
        }).join('');
        return '<Row>' + cellsXml + '</Row>';
      }).join('\n');
      var xml = '<?xml version="1.0" encoding="UTF-8"?>\n' +
        '<?mso-application progid="Excel.Sheet"?>\n' +
        '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"\n' +
        ' xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">\n' +
        ' <Worksheet ss:Name="' + escXml(sheet.name) + '">\n' +
        '  <Table>\n' + rowsXml + '\n  </Table>\n' +
        ' </Worksheet>\n</Workbook>';
      var blob = new Blob([xml], { type: 'application/vnd.ms-excel;charset=utf-8' });
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = filename || 'Bai_Tap_Excel.xls';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  };
})(window);
